def f(a, b):
    if a == 1:
        return 1
    return b * f(a - 1, b)

print(f(4, 6))

def g(n):
    if n == 0:
        return 0
    return n + g(n - 1)

print(g(5))

def f(n):
    if n <= 1:
        return 1
    return n * f(n - 1)

print(f(5))

def h(n):
    if n <= 1:
        return n
    return h(n - 1) + h(n - 2)

print(h(6))
